// The code is generated by the server and validated here before entering HTML.
export function createLoginMessage(to,code,fromAddress){
 if(!/^\d{6}$/.test(code))throw new Error('Invalid login code');
 const text=`Код входа в ZaPDF: ${code}\n\nВведите его на сайте. Код действует 10 минут.\nЕсли вы не запрашивали вход, просто проигнорируйте это письмо.\n\nZaPDF — zapdf.ru`;
 const html=`<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Код входа в ZaPDF</title></head><body style="margin:0;padding:0;background:#f4f4f4;color:#262626;font-family:Arial,Helvetica,sans-serif"><table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border-collapse:collapse;background:#f4f4f4"><tr><td align="center" style="padding:32px 16px"><table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border-collapse:separate;border-spacing:0;max-width:560px;background:#ffffff;border-radius:16px;overflow:hidden"><tr><td style="padding:25px 32px;background:#2d2d2d;color:#ffffff;font-size:23px;font-weight:700;letter-spacing:-0.5px">ZaPDF <span style="font-size:13px;font-weight:400;color:#e6e6e6;letter-spacing:0">&nbsp; / &nbsp;вход в аккаунт</span></td></tr><tr><td align="center" style="padding:40px 24px 36px"><h1 style="margin:0 0 12px;font-size:24px;line-height:1.3;color:#262626">Ваш код для входа</h1><p style="margin:0 0 26px;color:#2d2d2d;font-size:15px;line-height:1.6">Введите его на странице входа в ZaPDF.</p><div style="display:inline-block;padding:17px 22px;border-radius:12px;background:#efefef;color:#2d2d2d;font-size:32px;font-weight:700;line-height:1.2;letter-spacing:8px;font-variant-numeric:tabular-nums">${code}</div><p style="margin:26px 0 0;color:#2d2d2d;font-size:13px;line-height:1.7">Код действует <strong>10 минут</strong>.<br>Если вы не запрашивали вход, просто проигнорируйте это письмо.</p></td></tr><tr><td align="center" style="padding:20px 24px;background:#fafafa;color:#2d2d2d;font-size:12px;line-height:1.5">ZaPDF · документы с подписью<br>zapdf.ru</td></tr></table></td></tr></table></body></html>`;
 return {from:{name:'ZaPDF',address:fromAddress},to,subject:'Код входа в ZaPDF',text,html,headers:{'X-Mailru-Msgtype':'transactional'}};
}
